def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def is_equal_to_factorial_sum(number):
    digits = [int(d) for d in str(number)]
    factorial_sum = sum(factorial(d) for d in digits)
    return number == factorial_sum

def count_equal_numbers():
    count = 0
    for number in range(100, 1000):
        if is_equal_to_factorial_sum(number):
            count += 1
    return count

